'use strict';

/**
 * Thrown for malformed CSV input. `line` and `column` are 1-based; columns
 * count UTF-16 code units and a leading byte order mark is not counted.
 */
class CsvError extends Error {
  /**
   * @param {string} message Description of the problem, without the position.
   * @param {number} line 1-based line of the offending input.
   * @param {number} column 1-based column (UTF-16 code units).
   * @param {string} code Stable machine-readable identifier, e.g. `UNCLOSED_QUOTE`.
   */
  constructor(message, line, column, code) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

/** Values of `CsvError#code`. */
const CsvErrorCode = Object.freeze({
  UNCLOSED_QUOTE: 'UNCLOSED_QUOTE',
  UNEXPECTED_CHARACTER: 'UNEXPECTED_CHARACTER',
  DUPLICATE_HEADER: 'DUPLICATE_HEADER',
  FIELD_COUNT_MISMATCH: 'FIELD_COUNT_MISMATCH',
});

module.exports = { CsvError, CsvErrorCode };

