'use strict';

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'an array';
  return typeof value === 'object' ? 'an object' : `${typeof value} ${String(value)}`;
}

function assertOptionsObject(options, fnName) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`${fnName}: options must be an object, received ${describe(options)}`);
  }
}

function resolveDelimiter(value, fnName) {
  if (value === undefined) return DEFAULT_DELIMITER;
  if (
    typeof value !== 'string' ||
    value.length !== 1 ||
    value === '"' ||
    value === '\r' ||
    value === '\n'
  ) {
    throw new TypeError(
      `${fnName}: options.delimiter must be a single character other than '"', CR or LF, received ${describe(value)}`,
    );
  }
  return value;
}

function resolveBoolean(value, name, fnName) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${fnName}: options.${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

function resolveEol(value, fnName) {
  if (value === undefined) return DEFAULT_EOL;
  if (!ALLOWED_EOLS.includes(value)) {
    throw new TypeError(`${fnName}: options.eol must be '\\r\\n' or '\\n', received ${describe(value)}`);
  }
  return value;
}

/** Validates `parse`/`createParser` options. Unknown keys are ignored. */
function resolveParseOptions(options, fnName) {
  assertOptionsObject(options, fnName);
  return {
    delimiter: resolveDelimiter(options.delimiter, fnName),
    header: resolveBoolean(options.header, 'header', fnName),
    skipEmptyLines: resolveBoolean(options.skipEmptyLines, 'skipEmptyLines', fnName),
  };
}

/**
 * Validates `stringify` options. Unknown keys (such as `skipEmptyLines`) are
 * ignored so one options object can be shared with `parse`.
 */
function resolveStringifyOptions(options, fnName) {
  assertOptionsObject(options, fnName);
  const { header } = options;
  if (header !== undefined && header !== false) {
    if (!Array.isArray(header) || header.length === 0) {
      throw new TypeError(
        `${fnName}: options.header must be a non-empty array of column names, received ${describe(header)}`,
      );
    }
    header.forEach((name, index) => {
      if (typeof name !== 'string') {
        throw new TypeError(
          `${fnName}: options.header[${index}] must be a string, received ${describe(name)}`,
        );
      }
    });
  }
  return {
    delimiter: resolveDelimiter(options.delimiter, fnName),
    eol: resolveEol(options.eol, fnName),
    header: Array.isArray(header) ? header.slice() : null,
  };
}

module.exports = { describe, resolveParseOptions, resolveStringifyOptions };

