'use strict';

const { CsvError, CsvErrorCode } = require('./errors');
const { describe, resolveParseOptions } = require('./options');

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// Nothing of the current record has been read. A line break here is an empty line.
const RECORD_START = 0;
// The next character is the first of a field; its position is already recorded.
const FIELD_START = 1;
const UNQUOTED = 2;
const QUOTED = 3;
// A `"` was read inside a quoted field. The next character decides whether it
// was the first half of `""` or the closing quote, and may be in the next chunk.
const AFTER_QUOTE = 4;

/**
 * Incremental state machine behind both `parse` and `createParser`. It keeps
 * only the current field and record, so each chunk is read exactly once.
 */
class StreamParser {
  constructor(options, fnName) {
    const { delimiter, header, skipEmptyLines } = resolveParseOptions(options, fnName);
    this.delimiter = delimiter.charCodeAt(0);
    this.headerMode = header;
    this.skipEmptyLines = skipEmptyLines;
    this.columns = null;
    // Non-null only while the header record is being read.
    this.seenColumns = header ? new Set() : null;

    this.state = RECORD_START;
    this.sawInput = false;
    this.closedReason = null;
    // Position of the next unread character.
    this.line = 1;
    this.column = 1;
    // The last character read was a CR, so an LF next completes a CRLF.
    this.afterCR = false;

    this.record = [];
    this.field = '';
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.recordLine = 1;
    this.output = [];
  }

  write(chunk) {
    this.assertOpen('write');
    try {
      if (typeof chunk !== 'string') {
        throw new TypeError(`write: chunk must be a string, received ${describe(chunk)}`);
      }
      this.consume(chunk);
      return this.takeOutput();
    } catch (err) {
      this.closedReason = 'an earlier call threw';
      throw err;
    }
  }

  end() {
    this.assertOpen('end');
    try {
      this.finish();
      this.closedReason = 'end() was already called';
      return this.takeOutput();
    } catch (err) {
      this.closedReason = 'an earlier call threw';
      throw err;
    }
  }

  assertOpen(method) {
    if (this.closedReason !== null) {
      throw new Error(`${method}: the parser is closed because ${this.closedReason}`);
    }
  }

  takeOutput() {
    const records = this.output;
    this.output = [];
    return records;
  }

  consume(chunk) {
    const length = chunk.length;
    let i = 0;
    if (!this.sawInput) {
      if (length === 0) return;
      this.sawInput = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    while (i < length) {
      switch (this.state) {
        case RECORD_START:
          i = this.readRecordStart(chunk, i);
          break;
        case FIELD_START:
          i = this.readFieldStart(chunk, i);
          break;
        case UNQUOTED:
          i = this.readUnquoted(chunk, i);
          break;
        case QUOTED:
          i = this.readQuoted(chunk, i);
          break;
        default:
          i = this.readAfterQuote(chunk, i);
          break;
      }
    }
  }

  finish() {
    switch (this.state) {
      case RECORD_START:
        // Empty input, or the input ended with a line break.
        return;
      case QUOTED:
        throw new CsvError(
          'Unclosed quoted field',
          this.fieldLine,
          this.fieldColumn,
          CsvErrorCode.UNCLOSED_QUOTE,
        );
      default:
        this.endField();
        this.endRecord();
    }
  }

  readRecordStart(chunk, i) {
    const c = chunk.charCodeAt(i);
    if (this.afterCR) {
      this.afterCR = false;
      if (c === LF) return i + 1;
    }
    this.recordLine = this.line;
    this.markFieldStart();
    if (c === CR || c === LF) {
      this.advanceLine(c);
      if (!this.skipEmptyLines) {
        this.endField();
        this.endRecord();
      }
      return i + 1;
    }
    this.state = FIELD_START;
    return i;
  }

  readFieldStart(chunk, i) {
    if (chunk.charCodeAt(i) === QUOTE) {
      this.column++;
      this.state = QUOTED;
      return i + 1;
    }
    this.state = UNQUOTED;
    return i;
  }

  readUnquoted(chunk, i) {
    const { delimiter } = this;
    const length = chunk.length;
    let j = i;
    while (j < length) {
      const c = chunk.charCodeAt(j);
      if (c === delimiter || c === CR || c === LF) break;
      j++;
    }
    if (j > i) {
      this.field += chunk.slice(i, j);
      this.column += j - i;
    }
    if (j === length) return j;
    this.terminateField(chunk.charCodeAt(j));
    return j + 1;
  }

  readQuoted(chunk, i) {
    const length = chunk.length;
    let { line, column, afterCR } = this;
    let j = i;
    for (; j < length; j++) {
      const c = chunk.charCodeAt(j);
      if (c === QUOTE) break;
      if (c === CR) {
        line++;
        column = 1;
        afterCR = true;
      } else if (c === LF) {
        if (!afterCR) {
          line++;
          column = 1;
        }
        afterCR = false;
      } else {
        column++;
        afterCR = false;
      }
    }
    if (j > i) this.field += chunk.slice(i, j);
    this.line = line;
    this.column = column;
    this.afterCR = afterCR;
    if (j === length) return j;
    this.column++;
    this.afterCR = false;
    this.state = AFTER_QUOTE;
    return j + 1;
  }

  readAfterQuote(chunk, i) {
    const c = chunk.charCodeAt(i);
    if (c === QUOTE) {
      this.field += '"';
      this.column++;
      this.state = QUOTED;
      return i + 1;
    }
    if (c === this.delimiter || c === CR || c === LF) {
      this.terminateField(c);
      return i + 1;
    }
    throw new CsvError(
      `Unexpected character ${JSON.stringify(chunk[i])} after a closing quote`,
      this.line,
      this.column,
      CsvErrorCode.UNEXPECTED_CHARACTER,
    );
  }

  /** Ends the current field at `c`, which is the delimiter, CR or LF. */
  terminateField(c) {
    this.endField();
    if (c === this.delimiter) {
      this.column++;
      this.markFieldStart();
      this.state = FIELD_START;
      return;
    }
    this.advanceLine(c);
    this.endRecord();
    this.state = RECORD_START;
  }

  advanceLine(c) {
    this.line++;
    this.column = 1;
    this.afterCR = c === CR;
  }

  markFieldStart() {
    this.fieldLine = this.line;
    this.fieldColumn = this.column;
  }

  endField() {
    const value = this.field;
    this.field = '';
    if (this.seenColumns !== null) {
      if (this.seenColumns.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
          CsvErrorCode.DUPLICATE_HEADER,
        );
      }
      this.seenColumns.add(value);
    }
    this.record.push(value);
  }

  endRecord() {
    const record = this.record;
    this.record = [];
    if (!this.headerMode) {
      this.output.push(record);
      return;
    }
    if (this.columns === null) {
      this.columns = record;
      this.seenColumns = null;
      return;
    }
    this.output.push(this.toObject(record));
  }

  toObject(record) {
    const { columns } = this;
    if (record.length !== columns.length) {
      throw new CsvError(
        `Expected ${columns.length} ${plural(columns.length, 'field')} to match the header, found ${record.length}`,
        this.recordLine,
        1,
        CsvErrorCode.FIELD_COUNT_MISMATCH,
      );
    }
    const object = {};
    for (let k = 0; k < columns.length; k++) {
      const key = columns[k];
      if (key === '__proto__') {
        // Plain assignment would replace the prototype instead of adding a column.
        Object.defineProperty(object, key, {
          value: record[k],
          writable: true,
          enumerable: true,
          configurable: true,
        });
      } else {
        object[key] = record[k];
      }
    }
    return object;
  }
}

function plural(count, word) {
  return count === 1 ? word : `${word}s`;
}

/**
 * @typedef {object} ParseOptions
 * @property {string} [delimiter=','] One UTF-16 code unit other than `"`, CR or LF.
 * @property {boolean} [header=false] Use the first record as column names and return objects.
 * @property {boolean} [skipEmptyLines=false] Drop lines that contain no characters at all.
 */

/**
 * Parses a complete CSV document.
 *
 * @param {string} text
 * @param {ParseOptions} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>}
 * @throws {TypeError} If `text` is not a string or an option is invalid.
 * @throws {CsvError} If the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`parse: text must be a string, received ${describe(text)}`);
  }
  const parser = new StreamParser(options, 'parse');
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

/**
 * @typedef {object} CsvStreamParser
 * @property {(chunk: string) => Array<string[] | Record<string, string>>} write
 *   Feeds the next piece of input and returns the records it completed.
 * @property {() => Array<string[] | Record<string, string>>} end
 *   Signals the end of input and returns the remaining records.
 */

/**
 * Creates a parser for input that arrives in pieces. Records and errors are
 * the same as `parse` on the concatenated input, wherever the chunks split.
 * Once `end()` has been called or either method has thrown, both methods throw.
 *
 * @param {ParseOptions} [options]
 * @returns {CsvStreamParser}
 * @throws {TypeError} If an option is invalid.
 */
