'use strict';

const { describe, resolveStringifyOptions } = require('./options');

const SPACE = 0x20;
const BOM = 0xfeff;

function toText(value, rowIndex, fieldKey) {
  switch (typeof value) {
    case 'string':
      return value;
    case 'number':
    case 'boolean':
      return String(value);
    case 'undefined':
      return '';
    default:
      if (value === null) return '';
      throw new TypeError(
        `stringify: rows[${rowIndex}][${fieldKey}] must be a string, number, boolean, null or undefined, received ${describe(value)}`,
      );
  }
}

function needsQuotes(text, delimiter) {
  return (
    text.length > 0 &&
    (text.includes(delimiter) ||
      text.includes('"') ||
      text.includes('\r') ||
      text.includes('\n') ||
      text.charCodeAt(0) === SPACE ||
      text.charCodeAt(text.length - 1) === SPACE)
  );
}

function quote(text) {
  return `"${text.replace(/"/g, '""')}"`;
}

function recordTexts(row, rowIndex, header) {
  if (Array.isArray(row)) {
    const texts = new Array(row.length);
    for (let f = 0; f < row.length; f++) texts[f] = toText(row[f], rowIndex, f);
    return texts;
  }
  if (header !== null && typeof row === 'object' && row !== null) {
    return header.map((key) =>
      Object.prototype.hasOwnProperty.call(row, key)
        ? toText(row[key], rowIndex, JSON.stringify(key))
        : '',
    );
  }
  throw new TypeError(
    `stringify: rows[${rowIndex}] must be an array${header !== null ? ' or an object' : ''}, received ${describe(row)}`,
  );
}

function formatRecord(texts, delimiter, isFirstLine) {
  // An empty line would parse as [''] or be skipped by skipEmptyLines; `""` is unambiguous.
  if (texts.length === 1 && texts[0] === '') return '""';
  const fields = texts.map((text) => (needsQuotes(text, delimiter) ? quote(text) : text));
  let line = fields.join(delimiter);
  if (isFirstLine && line.charCodeAt(0) === BOM) {
    // parse drops a leading BOM, so it must not be the first character of the output.
    fields[0] = quote(texts[0]);
    line = fields.join(delimiter);
  }
  return line;
}

/**
 * @typedef {object} StringifyOptions
 * @property {string} [delimiter=','] One UTF-16 code unit other than `"`, CR or LF.
 * @property {'\r\n' | '\n'} [eol='\r\n'] Written after every record, including the last.
 * @property {string[]} [header] Column names. Written as the first row, and lets
 *   records be objects whose values are written in this order.
 */

/**
 * Serializes records to CSV text.
 *
 * @param {Array<Array<string | number | boolean | null | undefined> | Record<string, unknown>>} rows
 * @param {StringifyOptions} [options]
 * @returns {string}
 * @throws {TypeError} If `rows`, a record, a value or an option has an unsupported type.
 */
function stringify(rows, options = {}) {
  const { delimiter, eol, header } = resolveStringifyOptions(options, 'stringify');
  if (!Array.isArray(rows)) {
    throw new TypeError(`stringify: rows must be an array, received ${describe(rows)}`);
  }
  const lines = [];
