const assert = require('node:assert/strict');
const { parse } = require('../src/csv');

describe('parse: input type', () => {
  for (const value of [undefined, null, 42, true, {}, ['a,b'], Buffer.from('a,b'), Symbol('s')]) {
    it(`throws TypeError for non-string text (${typeof value === 'symbol' ? 'symbol' : JSON.stringify(value) ?? 'undefined'})`, () => {
      assert.throws(() => parse(value), TypeError);
    });
  }

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
  });

  it('returns [] for a string that is only a BOM', () => {
    assert.deepEqual(parse('\uFEFF'), []);
  });
});

describe('parse: basic records', () => {
  const cases = [
    ['single field', 'a', [['a']]],
    ['one record', 'a,b,c', [['a', 'b', 'c']]],
    ['two records with LF', 'a,b\nc,d', [['a', 'b'], ['c', 'd']]],
    ['CRLF separators', 'a,b\r\nc,d\r\n', [['a', 'b'], ['c', 'd']]],
    ['CR separators', 'a,b\rc,d\r', [['a', 'b'], ['c', 'd']]],
    ['mixed separators', 'a\r\nb\nc\rd', [['a'], ['b'], ['c'], ['d']]],
    ['LF then CR is two line breaks', 'a\n\rb', [['a'], [''], ['b']]],
    ['empty fields', ',,', [['', '', '']]],
    ['trailing delimiter gives trailing empty field', 'a,\nb,', [['a', ''], ['b', '']]],
    ['records may have different lengths', 'a\nb,c\nd,e,f', [['a'], ['b', 'c'], ['d', 'e', 'f']]],
    ['unicode is kept', 'café,日本語,😀\n', [['café', '日本語', '😀']]],
  ];
  for (const [name, input, expected] of cases) {
    it(name, () => {
      assert.deepEqual(parse(input), expected);
    });
  }
});

describe('parse: whitespace and quotes in unquoted fields', () => {
  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b \t,\t'), [[' a ', ' b \t', '\t']]);
  });

  it('treats " inside an unquoted field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c""d,e"'), [['a"b', 'c""d', 'e"']]);
  });

  it('treats a space before a quote as the start of an unquoted field', () => {
    assert.deepEqual(parse(' "a",b'), [[' "a"', 'b']]);
  });
});

describe('parse: quoted fields', () => {
  it('unwraps a quoted field', () => {
    assert.deepEqual(parse('"a","b"'), [['a', 'b']]);
  });

  it('reads "" inside quotes as one literal quote', () => {
    assert.deepEqual(parse('"say ""hi""",""""'), [['say "hi"', '"']]);
  });

  it('keeps delimiters, CR and LF inside quotes literally', () => {
    assert.deepEqual(parse('"a,b","c\r\nd","e\rf","g\nh"\n'), [['a,b', 'c\r\nd', 'e\rf', 'g\nh']]);
  });

  it('reads "" as an empty quoted field that is not an empty line', () => {
    assert.deepEqual(parse('""\n""'), [[''], ['']]);
    assert.deepEqual(parse('""\n""', { skipEmptyLines: true }), [[''], ['']]);
  });

  it('allows a quoted field to end at end of input', () => {
    assert.deepEqual(parse('a,"b"'), [['a', 'b']]);
  });

  it('allows a quoted field followed by CR, LF or CRLF', () => {
    assert.deepEqual(parse('"a"\r"b"\n"c"\r\n"d"'), [['a'], ['b'], ['c'], ['d']]);
  });
});

describe('parse: byte order mark', () => {
  it('ignores a leading BOM', () => {
    assert.deepEqual(parse('\uFEFFa,b'), [['a', 'b']]);
  });

  it('ignores a leading BOM before a quoted field', () => {
    assert.deepEqual(parse('\uFEFF"a",b'), [['a', 'b']]);
  });

  it('keeps a BOM that is not the first character', () => {
    assert.deepEqual(parse('a,\uFEFFb\n\uFEFFc'), [['a', '\uFEFFb'], ['\uFEFFc']]);
  });

  it('removes only one leading BOM', () => {
    assert.deepEqual(parse('\uFEFF\uFEFFa'), [['\uFEFFa']]);
  });
});

describe('parse: empty lines', () => {
  const cases = [
    ['a final line break does not start a record', 'a\n', [['a']], [['a']]],
    ['a final CRLF does not start a record', 'a\r\n', [['a']], [['a']]],
    ['a second final line break is an empty record', 'a\n\n', [['a'], ['']], [['a']]],
    ['a lone line break is one empty record', '\n', [['']], []],
    ['a lone CRLF is one empty record', '\r\n', [['']], []],
    ['leading empty lines', '\n\na', [[''], [''], ['a']], [['a']]],
    ['empty lines between records', 'a\r\n\r\n\nb', [['a'], [''], [''], ['b']], [['a'], ['b']]],
    ['CR-only empty lines', 'a\r\r\rb', [['a'], [''], [''], ['b']], [['a'], ['b']]],
    ['a line with only spaces is not empty', 'a\n \nb', [['a'], [' '], ['b']], [['a'], [' '], ['b']]],
    ['a line with only a delimiter is not empty', 'a\n,\nb', [['a'], ['', ''], ['b']], [['a'], ['', ''], ['b']]],
  ];
  for (const [name, input, withEmpty, skipped] of cases) {
    it(`${name} (skipEmptyLines false)`, () => {
      assert.deepEqual(parse(input), withEmpty);
      assert.deepEqual(parse(input, { skipEmptyLines: false }), withEmpty);
    });
    it(`${name} (skipEmptyLines true)`, () => {
      assert.deepEqual(parse(input, { skipEmptyLines: true }), skipped);
    });
  }
});

describe('parse: delimiter option', () => {
  for (const delimiter of [';', '\t', '|', ' ', 'x', 'é', '\uFEFF']) {
    it(`splits on ${JSON.stringify(delimiter)}`, () => {
      const input = `a${delimiter}b\n"c${delimiter}d"${delimiter}e`;
      assert.deepEqual(parse(input, { delimiter }), [['a', 'b'], [`c${delimiter}d`, 'e']]);
    });
  }

  it('treats commas as ordinary characters when another delimiter is set', () => {
    assert.deepEqual(parse('a,b;c', { delimiter: ';' }), [['a,b', 'c']]);
  });

  const invalid = ['', ',,', '"', '\r', '\n', '\r\n', '😀', null, 1, true, [','], {}];
  for (const delimiter of invalid) {
    it(`throws TypeError for delimiter ${JSON.stringify(delimiter) ?? String(delimiter)}`, () => {
      assert.throws(() => parse('a', { delimiter }), TypeError);
    });
  }
});

describe('parse: header option', () => {
  it('returns objects keyed by the header', () => {
    assert.deepEqual(parse('name,age\nAda,36\nAlan,41\n', { header: true }), [
      { name: 'Ada', age: '36' },
      { name: 'Alan', age: '41' },
    ]);
  });

  it('returns [] for a header-only input, with or without a final line break', () => {
    assert.deepEqual(parse('a,b', { header: true }), []);
    assert.deepEqual(parse('a,b\r\n', { header: true }), []);
    assert.deepEqual(parse('', { header: true }), []);
  });

  it('allows quoted and empty column names', () => {
    assert.deepEqual(parse('"a,b",\n1,2', { header: true }), [{ 'a,b': '1', '': '2' }]);
  });

  it('adds a __proto__ column as an own property without changing the prototype', () => {
    const [record] = parse('__proto__,constructor\nx,y', { header: true });
    assert.equal(Object.getPrototypeOf(record), Object.prototype);
    assert.deepEqual(Object.keys(record), ['__proto__', 'constructor']);
    assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, 'x');
    assert.equal(record.constructor, 'y');
  });

  it('treats an empty line as a one-field record', () => {
    assert.deepEqual(parse('a\n\nb', { header: true }), [{ a: '' }, { a: 'b' }]);
  });

  it('uses the first non-empty line as the header when skipEmptyLines is true', () => {
    assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [
      { a: '1', b: '2' },
    ]);
  });

  it('uses a leading empty line as a one-column header when skipEmptyLines is false', () => {
    assert.deepEqual(parse('\nx\ny', { header: true }), [{ '': 'x' }, { '': 'y' }]);
  });

  for (const header of [1, 'true', null, ['a']]) {
    it(`throws TypeError for header ${JSON.stringify(header)}`, () => {
      assert.throws(() => parse('a', { header }), TypeError);
    });
  }
});

describe('parse: options validation', () => {
  for (const options of [null, 'x', 5, []]) {
    it(`throws TypeError for options ${JSON.stringify(options)}`, () => {
      assert.throws(() => parse('a', options), TypeError);
    });
  }

  for (const skipEmptyLines of [1, 'yes', null]) {
    it(`throws TypeError for skipEmptyLines ${JSON.stringify(skipEmptyLines)}`, () => {
      assert.throws(() => parse('a', { skipEmptyLines }), TypeError);
    });
  }

  it('ignores options it does not know, such as eol', () => {
    assert.deepEqual(parse('a\nb', { eol: '\n', other: 1 }), [['a'], ['b']]);
  });

  it('does not modify the options object', () => {
    const options = Object.freeze({ delimiter: ';', header: true, skipEmptyLines: true });
    assert.deepEqual(parse('a;b\n1;2', options), [{ a: '1', b: '2' }]);
  });
});

