'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Asserts that parsing `input` throws a CsvError at the given position. */
function assertCsvError(input, options, { line, column, code }) {
  let caught;
  try {
    parse(input, options);
  } catch (err) {
    caught = err;
  }
  assert.ok(caught instanceof CsvError, `expected CsvError, got ${caught}`);
  assert.deepEqual(
    { line: caught.line, column: caught.column, code: caught.code },
    { line, column, code },
  );
  return caught;
}

describe('CsvError', () => {
  it('is a subclass of Error with name, line, column and code', () => {
    const err = new CsvError('Something broke', 3, 7, 'TEST');
    assert.ok(err instanceof Error);
    assert.ok(err instanceof CsvError);
    assert.equal(err.name, 'CsvError');
    assert.equal(err.line, 3);
    assert.equal(err.column, 7);
    assert.equal(err.code, 'TEST');
    assert.equal(err.message, 'Something broke at line 3, column 7');
    assert.ok(err.stack.includes('CsvError'));
  });
});

describe('errors: unclosed quoted field', () => {
  it('points at the opening quote of a field at the start of input', () => {
    assertCsvError('"abc', {}, { line: 1, column: 1, code: 'UNCLOSED_QUOTE' });
  });

  it('points at the opening quote after a delimiter', () => {
    assertCsvError('a,b,"c', {}, { line: 1, column: 5, code: 'UNCLOSED_QUOTE' });
  });

  it('points at the opening quote even when the field spans later lines', () => {
    assertCsvError('a\r\nb,"c\nd\r\ne', {}, { line: 2, column: 3, code: 'UNCLOSED_QUOTE' });
  });

  it('reports a quote that looked closed but was an escaped quote', () => {
    assertCsvError('x\n"a""', {}, { line: 2, column: 1, code: 'UNCLOSED_QUOTE' });
  });

  it('does not count a leading BOM as a column', () => {
    assertCsvError('﻿"abc', {}, { line: 1, column: 1, code: 'UNCLOSED_QUOTE' });
  });

  it('includes the position in the message', () => {
    const err = assertCsvError('a,"b', {}, { line: 1, column: 3, code: 'UNCLOSED_QUOTE' });
    assert.match(err.message, /line 1, column 3/);
  });
});

describe('errors: character after a closing quote', () => {
  it('points at the offending character', () => {
    assertCsvError('"a"b', {}, { line: 1, column: 4, code: 'UNEXPECTED_CHARACTER' });
  });

  it('rejects a space after the closing quote', () => {
    assertCsvError('a,"b" ,c', {}, { line: 1, column: 6, code: 'UNEXPECTED_CHARACTER' });
  });

  it('counts lines inside earlier quoted fields', () => {
    assertCsvError('"a\nb\r\nc"x', {}, { line: 3, column: 3, code: 'UNEXPECTED_CHARACTER' });
  });

  it('counts CR, LF and CRLF each as one line break', () => {
    assertCsvError('a\rb\nc\r\nd\n\r"e"f', {}, { line: 6, column: 4, code: 'UNEXPECTED_CHARACTER' });
  });

  it('counts columns in UTF-16 code units', () => {
    // 😀 is two code units, so the closing quote is at column 4 and x at column 5.
    assertCsvError('"😀"x', {}, { line: 1, column: 5, code: 'UNEXPECTED_CHARACTER' });
  });

  it('rejects a comma after a quote when the delimiter is something else', () => {
    assertCsvError('"a",b', { delimiter: ';' }, { line: 1, column: 4, code: 'UNEXPECTED_CHARACTER' });
  });

  it('names the character in the message', () => {
    const err = assertCsvError('"a"z', {}, { line: 1, column: 4, code: 'UNEXPECTED_CHARACTER' });
    assert.match(err.message, /"z"/);
  });
});

describe('errors: duplicate header name', () => {
  it('points at the start of the second occurrence', () => {
    assertCsvError('a,b,a\n1,2,3', { header: true }, { line: 1, column: 5, code: 'DUPLICATE_HEADER' });
  });

  it('points at the opening quote of a quoted duplicate', () => {
    assertCsvError('abc,"abc"', { header: true }, { line: 1, column: 5, code: 'DUPLICATE_HEADER' });
  });

  it('detects duplicate empty names at the start of the second empty field', () => {
    assertCsvError('a,,', { header: true }, { line: 1, column: 4, code: 'DUPLICATE_HEADER' });
  });

  it('uses the header line after skipped empty lines', () => {
    assertCsvError('\n\nx,x', { header: true, skipEmptyLines: true }, { line: 3, column: 3, code: 'DUPLICATE_HEADER' });
  });

  it('is case-sensitive and does not trim', () => {
    assert.deepEqual(parse('a,A, a\n1,2,3', { header: true }), [{ a: '1', A: '2', ' a': '3' }]);
  });

  it('is only checked in header mode', () => {
    assert.deepEqual(parse('a,a'), [['a', 'a']]);
  });

  it('is an error even when the input has only a header', () => {
    assertCsvError('a,a', { header: true }, { line: 1, column: 3, code: 'DUPLICATE_HEADER' });
  });
});

describe('errors: wrong number of fields in header mode', () => {
  it('rejects a record with fewer fields at that line, column 1', () => {
