'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Runs `fn` and captures either its result or the identifying fields of its error. */
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    return {
      error: { name: err.name, line: err.line, column: err.column, code: err.code, message: err.message },
    };
  }
}

function parseInChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

function splitAt(text, points) {
  const chunks = [];
  let previous = 0;
  for (const point of points) {
    chunks.push(text.slice(previous, point));
    previous = point;
  }
  chunks.push(text.slice(previous));
  return chunks;
}

describe('createParser: write and end', () => {
  it('returns each record from the write whose chunk holds its line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b'), []);
    assert.deepEqual(parser.write(',c\nd,'), [['a', 'b', 'c']]);
    assert.deepEqual(parser.write('e\r\nf\n'), [['d', 'e'], ['f']]);
    assert.deepEqual(parser.write('g'), []);
    assert.deepEqual(parser.end(), [['g']]);
  });

  it('returns a record ended by CR immediately, before knowing whether LF follows', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb'), []);
    assert.deepEqual(parser.end(), [['b']]);
  });

  it('does not return a record for the LF half of a split CRLF', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.end(), []);
  });

  it('accepts empty chunks', () => {
    const parser = createParser();
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.write('a'), []);
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.end(), [['a']]);
  });

  it('returns [] from end for no input', () => {
    assert.deepEqual(createParser().end(), []);
  });

  it('strips a BOM that arrives after empty chunks', () => {
    assert.deepEqual(parseInChunks(['', '', '﻿a'], {}), [['a']]);
  });

  it('keeps a BOM at the start of a later chunk', () => {
    assert.deepEqual(parseInChunks(['a', '﻿b'], {}), [['a﻿b']]);
  });

  it('returns objects in header mode and never returns the header', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('x,y\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ x: '1', y: '2' }]);
    assert.deepEqual(parser.end(), [{ x: '3', y: '' }]);
  });

  it('applies skipEmptyLines and delimiter options', () => {
    const parser = createParser({ delimiter: '\t', skipEmptyLines: true });
    assert.deepEqual(parser.write('a\tb\n\n\r\n'), [['a', 'b']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns a fresh array from every call', () => {
    const parser = createParser();
    const first = parser.write('a\n');
    first.push('mutated');
    assert.deepEqual(parser.write('b\n'), [['b']]);
  });
});

describe('createParser: invalid use', () => {
  it('validates options like parse', () => {
    assert.throws(() => createParser({ delimiter: '""' }), TypeError);
    assert.throws(() => createParser({ header: 'yes' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });

  for (const chunk of [undefined, null, 1, {}, Buffer.from('a')]) {
    it(`write throws TypeError for a ${chunk === null ? 'null' : typeof chunk} chunk`, () => {
      assert.throws(() => createParser().write(chunk), TypeError);
    });
  }

  it('throws from both methods after end()', () => {
    const parser = createParser();
    parser.end();
    assert.throws(() => parser.write('a'), { name: 'Error', message: /closed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
  });

  it('throws from both methods after write throws a CsvError', () => {
    const parser = createParser();
