'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { stringify } = require('../src/csv');

describe('stringify: rows and records', () => {
  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('joins fields with commas and ends every record with CRLF', () => {
    assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  });

  it('writes a single empty-string field as ""', () => {
    assert.equal(stringify([['']]), '""\r\n');
    assert.equal(stringify([['a'], [''], ['b']]), 'a\r\n""\r\n""\r\nb\r\n'.replace('""\r\n""', '""'));
  });

  it('writes a single null or undefined field as "" too', () => {
    assert.equal(stringify([[null], [undefined]]), '""\r\n""\r\n');
  });

  it('writes several empty fields as bare delimiters', () => {
    assert.equal(stringify([['', ''], ['', '', '']]), ',\r\n,,\r\n');
  });

  it('writes an empty record as an empty line', () => {
    assert.equal(stringify([[], ['a']]), '\r\na\r\n');
  });

  it('treats holes in sparse arrays as empty fields', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([['a', , 'c']]), 'a,,c\r\n');
  });

  for (const rows of [undefined, null, 'a,b', { 0: ['a'] }, 3]) {
    it(`throws TypeError for rows ${JSON.stringify(rows) ?? 'undefined'}`, () => {
      assert.throws(() => stringify(rows), TypeError);
    });
  }

  for (const row of ['a', null, undefined, { a: 1 }, 7]) {
    it(`throws TypeError for record ${JSON.stringify(row) ?? 'undefined'} without a header`, () => {
      assert.throws(() => stringify([['ok'], row]), /rows\[1\]/);
    });
  }

  it('does not modify the rows', () => {
    const rows = Object.freeze([Object.freeze(['a', 'b"c']), Object.freeze([1, null])]);
    assert.equal(stringify(rows), 'a,"b""c"\r\n1,\r\n');
  });
});

describe('stringify: values', () => {
  it('writes strings as is and numbers and booleans with String()', () => {
    assert.equal(
      stringify([['text', 0, -0, 1.5, -2, 1e21, NaN, Infinity, true, false]]),
      'text,0,0,1.5,-2,1e+21,NaN,Infinity,true,false\r\n',
    );
  });

  it('writes null and undefined as empty fields', () => {
    assert.equal(stringify([[null, 'a', undefined]]), ',a,\r\n');
  });

  const invalid = [
    ['object', {}],
    ['array', ['nested']],
    ['Date', new Date(0)],
    ['symbol', Symbol('s')],
    ['bigint', 10n],
    ['function', () => 'x'],
  ];
  for (const [name, value] of invalid) {
    it(`throws TypeError for a ${name} value and names its position`, () => {
      assert.throws(() => stringify([['a'], ['b', value]]), {
        name: 'TypeError',
        message: /rows\[1\]\[1\]/,
      });
    });
  }
});

describe('stringify: quoting', () => {
  const cases = [
    ['a delimiter', 'a,b', '"a,b"'],
    ['a quote, doubled', 'say "hi"', '"say ""hi"""'],
    ['only a quote', '"', '""""'],
    ['a CR', 'a\rb', '"a\rb"'],
    ['an LF', 'a\nb', '"a\nb"'],
    ['a CRLF', 'a\r\nb', '"a\r\nb"'],
    ['a leading space', ' a', '" a"'],
    ['a trailing space', 'a ', '"a "'],
    ['only a space', ' ', '" "'],
  ];
  for (const [name, value, expected] of cases) {
    it(`quotes a field containing ${name}`, () => {
      assert.equal(stringify([[value, 'x']]), `${expected},x\r\n`);
    });
  }

  it('does not quote interior spaces, tabs or other characters', () => {
    assert.equal(stringify([['a b', '\ta\t', "it's", 'café 😀']]), "a b,\ta\t,it's,café 😀\r\n");
  });

  it('quotes for the configured delimiter only', () => {
    assert.equal(stringify([['a,b', 'c;d']], { delimiter: ';' }), 'a,b;"c;d"\r\n');
    assert.equal(stringify([['a\tb', 'c']], { delimiter: '\t' }), '"a\tb"\tc\r\n');
  });

  it('quotes a first field that starts with a BOM so parse keeps it', () => {
    assert.equal(stringify([['﻿a', '﻿b'], ['﻿c']]), '"﻿a",﻿b\r\n﻿c\r\n');
  });

  it('quotes an empty first field when the delimiter is a BOM', () => {
    assert.equal(stringify([['', 'a'], ['', 'b']], { delimiter: '﻿' }), '""﻿a\r\n﻿b\r\n');
  });
});

describe('stringify: options', () => {
  it('uses LF when eol is "\\n"', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('accepts eol "\\r\\n" explicitly', () => {
    assert.equal(stringify([['a']], { eol: '\r\n' }), 'a\r\n');
  });

  for (const eol of ['\r', '', 'CRLF', '\n\r', null, 10]) {
    it(`throws TypeError for eol ${JSON.stringify(eol)}`, () => {
      assert.throws(() => stringify([['a']], { eol }), TypeError);
    });
  }

  for (const delimiter of ['', ';;', '"', '\r', '\n', null, 0]) {
    it(`throws TypeError for delimiter ${JSON.stringify(delimiter)}`, () => {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    });
  }

  it('validates options even when there are no rows', () => {
    assert.throws(() => stringify([], { eol: '\r' }), TypeError);
  });

  for (const options of [null, 'x', []]) {
    it(`throws TypeError for options ${JSON.stringify(options)}`, () => {
      assert.throws(() => stringify([['a']], options), TypeError);
    });
  }

  it('ignores options meant for parse, such as skipEmptyLines', () => {
    assert.equal(stringify([['a']], { skipEmptyLines: true }), 'a\r\n');
  });
});

describe('stringify: header option', () => {
  const header = ['name', 'note'];

  it('writes the header first, then object values in header order', () => {
    const rows = [
      { note: 'x', name: 'Ada' },
      { name: 'Alan', note: 'y, z' },
    ];
    assert.equal(stringify(rows, { header }), 'name,note\r\nAda,x\r\nAlan,"y, z"\r\n');
  });

  it('writes a missing key as an empty field and ignores extra keys', () => {
    assert.equal(stringify([{ name: 'Ada', age: 36 }], { header }), 'name,note\r\nAda,\r\n');
  });

  it('ignores inherited properties', () => {
    const row = Object.create({ note: 'inherited' });
    row.name = 'Ada';
    assert.equal(stringify([row], { header: ['name', 'note', 'toString'] }), 'name,note,toString\r\nAda,,\r\n');
  });

  it('accepts array records alongside objects', () => {
    assert.equal(stringify([['1', '2'], { name: '3' }], { header }), 'name,note\r\n1,2\r\n3,\r\n');
  });

  it('writes only the header when there are no rows', () => {
    assert.equal(stringify([], { header }), 'name,note\r\n');
  });

  it('quotes header names like any other field', () => {
    assert.equal(stringify([], { header: ['a,b', ' c', 'd"e'] }), '"a,b"," c","d""e"\r\n');
  });

  it('writes a single empty header name as ""', () => {
    assert.equal(stringify([{ '': 'v' }], { header: [''] }), '""\r\nv\r\n');
  });

  it('treats header: false as no header', () => {
    assert.equal(stringify([['a']], { header: false }), 'a\r\n');
  });

  it('applies the value rules to object values', () => {
    assert.equal(stringify([{ name: null, note: 5 }], { header }), 'name,note\r\n,5\r\n');
    assert.throws(() => stringify([{ name: {} }], { header }), { name: 'TypeError', message: /rows\[0\]\["name"\]/ });
  });

  for (const bad of [true, 'name', [], [1], ['a', null], {}]) {
    it(`throws TypeError for header ${JSON.stringify(bad)}`, () => {
      assert.throws(() => stringify([], { header: bad }), TypeError);
    });
  }

  for (const row of [null, 'Ada', 5]) {
    it(`throws TypeError for record ${JSON.stringify(row)} in header mode`, () => {
      assert.throws(() => stringify([row], { header }), { name: 'TypeError', message: /rows\[0\]/ });
    });
  }
});

