'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const csv = require('../src/csv');

const { parse, createParser, stringify, CsvError } = csv;

/** Small deterministic PRNG (mulberry32) so failures are reproducible. */
function prng(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Characters that exercise every quoting rule, plus the delimiters under test.
const ALPHABET = ['a', 'b', 'Z', '0', ' ', ',', ';', '\t', '"', '\r', '\n', '\r\n', '﻿', 'é', '😀', 'x'];

function randomField(random) {
  const length = Math.floor(random() * 6);
  const parts = [];
  for (let i = 0; i < length; i++) parts.push(ALPHABET[Math.floor(random() * ALPHABET.length)]);
  return parts.join('');
}

function randomRows(random) {
  const rows = [];
  const count = 1 + Math.floor(random() * 6);
  for (let r = 0; r < count; r++) {
    const row = [];
    const width = 1 + Math.floor(random() * 4);
    for (let f = 0; f < width; f++) row.push(random() < 0.2 ? '' : randomField(random));
    rows.push(row);
  }
  return rows;
}

function parseInRandomChunks(text, options, random) {
  const parser = createParser(options);
  const records = [];
  let i = 0;
  while (i < text.length) {
    const size = 1 + Math.floor(random() * 4);
    records.push(...parser.write(text.slice(i, i + size)));
    i += size;
  }
  records.push(...parser.end());
  return records;
}

describe('module exports', () => {
  it('exports exactly parse, createParser, stringify and CsvError', () => {
    assert.deepEqual(Object.keys(csv).sort(), ['CsvError', 'createParser', 'parse', 'stringify']);
    assert.equal(typeof parse, 'function');
    assert.equal(typeof createParser, 'function');
    assert.equal(typeof stringify, 'function');
    assert.ok(CsvError.prototype instanceof Error);
  });
});

describe('round trip: parse(stringify(rows, opts), opts) returns rows', () => {
  const fixed = [
    [['']],
    [[''], [''], ['']],
    [['', '']],
    [['a'], [''], ['b']],
    [[' '], ['"'], ['\r'], ['\n'], ['\r\n']],
    [['﻿'], ['﻿a', 'b']],
    [['', '﻿']],
    [['a,b', 'c;d', 'e\tf', 'g h']],
    [['😀', 'é'], ['x﻿']],
  ];
  const delimiters = [',', ';', '\t', ' ', '﻿', 'x'];
  const eols = ['\r\n', '\n'];

  for (const delimiter of delimiters) {
    for (const eol of eols) {
      for (const skipEmptyLines of [false, true]) {
        const options = { delimiter, eol, skipEmptyLines };
        const label = `delimiter ${JSON.stringify(delimiter)}, eol ${JSON.stringify(eol)}, skipEmptyLines ${skipEmptyLines}`;

        it(`fixed edge cases (${label})`, () => {
          for (const rows of fixed) {
            assert.deepEqual(parse(stringify(rows, options), options), rows, JSON.stringify(rows));
          }
        });

        it(`random rows through parse and chunked createParser (${label})`, () => {
          const random = prng(delimiters.indexOf(delimiter) * 100 + eol.length * 10 + Number(skipEmptyLines));
          for (let n = 0; n < 150; n++) {
            const rows = randomRows(random);
            const text = stringify(rows, options);
            assert.deepEqual(parse(text, options), rows, JSON.stringify({ rows, text }));
            assert.deepEqual(parseInRandomChunks(text, options, random), rows, JSON.stringify({ rows, text }));
          }
        });
      }
    }
  }
});

describe('round trip: header mode', () => {
  it('turns objects into CSV and back into objects of strings', () => {
    const header = ['id', 'name', 'note'];
    const rows = [
      { id: 1, name: 'Ada', note: 'said "hi", then left' },
      { id: 2, name: ' Alan ', note: 'line1\r\nline2' },
      { id: 3, name: '' },
    ];
    const text = stringify(rows, { header });
    assert.deepEqual(parse(text, { header: true }), [
      { id: '1', name: 'Ada', note: 'said "hi", then left' },
      { id: '2', name: ' Alan ', note: 'line1\r\nline2' },
      { id: '3', name: '', note: '' },
    ]);
  });

  it('round-trips a header-only document to []', () => {
    assert.deepEqual(parse(stringify([], { header: ['a', 'b'] }), { header: true }), []);
  });

  it('round-trips a single-column table with empty values', () => {
    const text = stringify([{ only: '' }, {}, { only: 'v' }], { header: ['only'], eol: '\n' });
    assert.equal(text, 'only\n""\n""\nv\n');
    assert.deepEqual(parse(text, { header: true, skipEmptyLines: true }), [{ only: '' }, { only: '' }, { only: 'v' }]);
  });

  it('streams a stringified document through createParser in header mode', () => {
    const header = ['k', 'v'];
    const rows = Array.from({ length: 200 }, (_, i) => ({ k: `key${i}`, v: `"${i}"\n` }));
    const text = stringify(rows, { header, delimiter: ';' });
    const random = prng(7);
    const parsed = parseInRandomChunks(text, { header: true, delimiter: ';' }, random);
    assert.deepEqual(parsed, rows);
  });
});

describe('round trip: parse then stringify', () => {
  it('normalizes line endings and quoting but keeps every value', () => {
    const input = 'a,"b"\n"c""d","e\nf"\r\n';
    const rows = parse(input);
    assert.equal(stringify(rows), 'a,b\r\n"c""d","e\nf"\r\n');
    assert.deepEqual(parse(stringify(rows)), rows);
  });
});

