node -e '
const { parse, stringify, createParser } = require("./src/csv");
const rows = Array.from({ length: 200000 }, (_, i) => [String(i), "plain text value", "with, comma", "quote \"x\"", "multi\nline"]);
let t = Date.now(); const text = stringify(rows); const ts = Date.now() - t;
t = Date.now(); const out = parse(text); const tp = Date.now() - t;
t = Date.now(); const p = createParser(); let n = 0; for (let i = 0; i < text.length; i += 4096) n += p.write(text.slice(i, i + 4096)).length; n += p.end().length; const tc = Date.now() - t;
console.log(`${(text.length/1e6).toFixed(1)}M chars: stringify ${ts}ms, parse ${tp}ms, 4K-chunk stream ${tc}ms, records ${out.length}/${n}`);
'

